// for forward compatibility.
//
// OrchestrationCore — authoritative state for plans, approvals, todos,
// and subagent lineage. Mirrors the Rust mp-orchestration crate records and
// their snake_case wire encodings. Single writer for plan/approval/todo
// transitions and lineage edges.
type OrchestrationCoreServiceServer interface {
	// List plans for a run. Plans are ordered by creation time ascending.
	ListPlans(context.Context, *ListPlansRequest) (*ListPlansResponse, error)
	// Fetch a single plan by id.
	GetPlan(context.Context, *GetPlanRequest) (*GetPlanResponse, error)
	// Transition a plan to a new state. Rejects illegal transitions.
	TransitionPlan(context.Context, *TransitionPlanRequest) (*TransitionPlanResponse, error)
	// Create a plan directly in PROPOSED state with real steps, supplied by the
	// model via the `plan.propose` control tool during a plan-mode run
	// (chat-wave2-specs plan-gate §2.1-2.2). Unlike the zero-step `draft` plan
	// session-core auto-creates at run start for the retrospective execution
	// log (`create_plan`), this is the plan a user actually reviews and edits
	// before granting an autonomy rung.
	ProposePlan(context.Context, *ProposePlanRequest) (*ProposePlanResponse, error)
	// List todos for a thread (and optionally scoped to a run).
	ListTodos(context.Context, *ListTodosRequest) (*ListTodosResponse, error)
	// Fetch a single todo by id.
	GetTodo(context.Context, *GetTodoRequest) (*GetTodoResponse, error)
	// Transition a todo to a new state. Rejects illegal transitions.
	TransitionTodo(context.Context, *TransitionTodoRequest) (*TransitionTodoResponse, error)
	// Create an approval request and pause the run for it. Inserts the durable
	// approval record and broadcasts APPROVAL state-change + RUN_PAUSED_FOR_APPROVAL
	// so operator surfaces show the pause. Called by execution-core when a step's
	// permission posture is "ask" and the tool is risky (HITL gate).
	CreateApproval(context.Context, *CreateApprovalRequest) (*CreateApprovalResponse, error)
	// List approvals for a run (and optionally scoped to a step).
	ListApprovals(context.Context, *ListApprovalsRequest) (*ListApprovalsResponse, error)
	// List all PENDING (state = REQUESTED) approvals, optionally scoped to one
	// org. An empty org_id returns every pending approval across all orgs and is
	// INTERNAL-ONLY — used by model-gateway to rehydrate its in-memory approval
	// cache on boot so a restart never silently drops a pending HITL gate. A
	// non-empty org_id scopes the result to that tenant (IDOR-safe read-through).
	// (D-1) The request/response messages are org-suffixed to avoid colliding
	// with the gateway-service ListPendingApprovals* messages in this package.
	ListPendingApprovals(context.Context, *OrgPendingApprovalsRequest) (*OrgPendingApprovalsResponse, error)
	// Fetch a single approval by id.
	GetApproval(context.Context, *GetApprovalRequest) (*GetApprovalResponse, error)
	// Record a decision (granted, denied, or timed_out) on an approval.
	DecideApproval(context.Context, *DecideApprovalRequest) (*DecideApprovalResponse, error)
	// Consume a granted loop-mode approval exactly once (build plan WS03 S2). The
	// durable Do loop that paused for the approval calls this when it re-enters, so
	// a granted approval is executed by the loop once and never also by the cold
	// delivery worker. Caller-scoped (user bearer), not service-only.
	ConsumeApproval(context.Context, *ConsumeApprovalRequest) (*ConsumeApprovalResponse, error)
	// Claim due durable approval deliveries for an authenticated internal
	// worker. Claims are tenant-scoped, leased, and opaque; the caller identity
	// is derived from its verified service credential, never from this request.
	ClaimApprovalDeliveries(context.Context, *ClaimApprovalDeliveriesRequest) (*ClaimApprovalDeliveriesResponse, error)
	// Fetch the exact immutable action descriptor for an active delivery lease.
	// This is service-only and lease-bound; normal approval readers never
	// receive descriptor content.
	GetApprovalContinuation(context.Context, *GetApprovalContinuationRequest) (*GetApprovalContinuationResponse, error)
	// Record the immutable receipt that a verified worker has begun the exact
	// descriptor-backed continuation. The worker supplies only its active lease;
	// Session Core derives fingerprint/version from retained descriptor data.
	RecordApprovalContinuationStarted(context.Context, *RecordApprovalContinuationStartedRequest) (*RecordApprovalContinuationStartedResponse, error)
	// Append the terminal outcome for a started continuation. Completion requires
	// an authoritative provider receipt; this alone does not settle the outbox.
	RecordApprovalContinuationOutcome(context.Context, *RecordApprovalContinuationOutcomeRequest) (*RecordApprovalContinuationOutcomeResponse, error)
	// Acknowledge a claimed delivery as retryable or terminal. There is no
	// delivered outcome until Execution Core can present a durable, authenticated
	// continuation receipt proving that the paused work actually restarted.
	AcknowledgeApprovalDelivery(context.Context, *AcknowledgeApprovalDeliveryRequest) (*AcknowledgeApprovalDeliveryResponse, error)
	// Ask the run's owner a question (build plan WS14 S3). A question is a pause
	// kind with its own store, never an approval: an answer is information, not an
	// authority grant, so it lives in `run_questions` and never reads as a grant.
	// Refused for a zero-retention or waived run, and for a ZDR or waived caller.
	CreateRunQuestion(context.Context, *CreateRunQuestionRequest) (*CreateRunQuestionResponse, error)
	// List the caller's own questions for a run. Owner-only; an overdue
	// question is reported EXPIRED.
	ListRunQuestions(context.Context, *ListRunQuestionsRequest) (*ListRunQuestionsResponse, error)
	// Answer (or skip) a requested question once. An identical retry is an
	// idempotent replay; a different second answer is refused.
	AnswerRunQuestion(context.Context, *AnswerRunQuestionRequest) (*AnswerRunQuestionResponse, error)
	// Fetch the subagent lineage for a thread.
	GetSubagentLineage(context.Context, *GetSubagentLineageRequest) (*GetSubagentLineageResponse, error)
	// Attach a subagent lineage edge (parent_run_id -> child_run_id).
	AttachSubagent(context.Context, *AttachSubagentRequest) (*AttachSubagentResponse, error)
	// Assemble the Verevon Proof Bundle for one run — the portable evidence
	// record defined in proof_bundle.proto. Read-only; org-scoped.
	GetRunProofBundle(context.Context, *GetRunProofBundleRequest) (*GetRunProofBundleResponse, error)
	// Aggregate Verified Outcome Foundation metrics across every run for one
	// organization (roadmap P1 item 5) — verified completion, false success,
	// human approval effort, and verification coverage. Read-only; org-scoped.
	GetVerificationMetrics(context.Context, *GetVerificationMetricsRequest) (*GetVerificationMetricsResponse, error)
	// Stream orchestration events for a run. Server-streaming over gRPC;
	// SSE-compatible at the gateway (/v1/runs/{id}/events).
	StreamRunEvents(*StreamRunEventsRequest, grpc.ServerStreamingServer[OrchestrationEvent]) error
	// Publish a caller-supplied orchestration event into the run's broadcast
	// (and bounded replay buffer) without owning the durable record behind it.
	// Used by execution-core to surface live worker progress — e.g. the browser
	// agent's dispatched actions and received observations — on the run-event
	// stream. The server assigns the monotonic event_id and timestamp; callers
	// leave them empty. Best-effort from the caller's perspective: a failure
	// here must never fail the underlying work.
	RecordOrchestrationEvent(context.Context, *RecordOrchestrationEventRequest) (*RecordOrchestrationEventResponse, error)
	mustEmbedUnimplementedOrchestrationCoreServiceServer()
}

